    {
        "name": "Cloacal Prolapse",
        "name_ja": "総排泄腔脱",
        "symptoms": {"tissue_protruding_from_vent", "straining", "bloody_droppings", "lethargy", "appetite_loss"},
        "description": "Cloacal Prolapse involves protrusion of an organ or tissue from its normal anatomical position.",
        "description_ja": "排泄孔からの総排泄腔組織の脱出で、いきみ、感染、腫瘤が原因となる。",
        "urgency": "emergency",
        "recommended_tests": ["physical_exam", "cloacal_culture", "radiography", "biopsy"],
        "causes": "Caused by physical trauma to reproductive tissue. Common causes include falls, cage injuries, handling accidents, bite wounds from conspecifics or predators, and environmental hazards. In bird, their avian with air sacs and unique respiratory system characteristics may predispose to specific types of injury. Secondary complications include infection, delayed healing, and chronic pain.",
        "causes_ja": "生殖器系組織への物理的外傷が原因。転落・ケージ損傷・取扱い事故・同居個体や捕食者からの咬傷・環境危険物が一般的原因。鳥の解剖学的特性が特定の損傷タイプへの素因となりうる。二次合併症として感染・治癒遅延・慢性疼痛がある。",
        "pathophysiology": "Traumatic injury to reproductive tissue in bird causes direct mechanical tissue damage including contusion, laceration, or fracture. The acute inflammatory response leads to edema, hemorrhage, and pain. Secondary complications include bacterial contamination, infection, and delayed healing. In bird, stress from the injury may trigger additional systemic complications due to their avian with air sacs and unique respiratory system physiology.",
        "pathophysiology_ja": "鳥の生殖器系組織への外傷性損傷は、挫傷・裂傷・骨折を含む直接的な機械的組織損傷を引き起こす。急性炎症反応により浮腫・出血・疼痛が生じる。二次合併症として細菌汚染・感染・治癒遅延がある。鳥では損傷からのストレスが追加の全身合併症を引き起こしうる。",
        "treatment": "Clean prolapsed tissue with warm sterile saline. Apply hypertonic sugar paste (50% dextrose) to reduce edema for 10-15 minutes. Gently replace tissue with lubricated cotton-tipped applicator. Place purse-string suture (3-0 or 4-0 absorbable) leaving opening for droppings. Meloxicam 0.5 mg/kg IM/PO q12-24h. Treat underlying cause (egg binding, cloacitis, papillomatosis). SC fluids. Remove if necrotic tissue present; surgical resection may be needed.",
        "treatment_ja": "鳥における総排泄腔脱の治療: 抗菌薬（培養感受性に基づく）。ネブライゼーション。酸素療法（重症時）。保温。栄養サポート。環境改善（換気・粉塵低減）。",
        "prevention": "適切な飼育管理、バランスの取れた栄養、定期的な獣医師による健康診断、ストレス軽減、初期症状の早期治療が予防に重要である。",
        "prevention_ja": "予防には適切な飼育管理（適切な食事・清潔な環境・最適な温湿度）；定期的な獣医師の健康診断；新規動物の検疫；ストレス軽減；種特異的予防措置が含まれる",
        "prognosis": "予後は重症度、治療の時期、治療への反応に依存する。早期介入により転帰が改善する。",
        "prognosis_ja": "外傷の予後は損傷の重症度と合併症の有無に依存する。軽度外傷は適切な創傷管理で予後良好。重度外傷、多発骨折、脊髄損傷は予後慎重〜不良。早期治療と適切な疼痛管理が回復を促進する。",
        "onset_pattern": {"acute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
    {
        "name": "Cloacal Papillomatosis",
        "name_ja": "総排泄腔乳頭腫症",
        "symptoms": {"tissue_protruding_from_vent", "bloody_droppings", "straining", "weight_loss", "foul_smelling_discharge"},
        "description": "Cloacal Papillomatosis is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "パピローマウイルスによる総排泄腔の腫瘤で、一部の種では胆管癌と関連する。",
        "urgency": "moderate",
        "recommended_tests": ["biopsy", "histopathology", "cloacal_exam", "PCR_papillomavirus"],
        "causes": "",
        "causes_ja": "オウムにおける総排泄腔乳頭腫症の原因: ウイルス病原体による感染。直接接触、飛沫・空気感染、媒介物、ベクター媒介が感染経路。免疫抑制、ストレス、過密飼育、ワクチン未接種が感受性を高める。",
        "pathophysiology": "The pathological process involves tissue injury, inflammatory response, and progressive functional impairment. Without intervention, compensatory mechanisms may be overwhelmed, leading to clinical deterioration.",
        "pathophysiology_ja": "総排泄腔乳頭腫症はオウムにおけるウイルス感染症である。ウイルスは特定の受容体を介して宿主細胞に侵入し、細胞内機構を利用して複製する。直接的な細胞変性効果（細胞溶解、アポトーシス、標的臓器の組織壊死）を引き起こす。自然免疫（インターフェロン、NK細胞）および適応免疫（抗体、細胞性免疫）の宿主免疫応答が免疫病理に寄与することがある。ウイルス血症により病原体が複数の臓器系に播種される可能性があり、免疫抑制により二次的な細菌・真菌感染のリスクが高まる。",
        "treatment": "Surgical excision or cryotherapy under isoflurane. Recurrence common (herpesvirus-associated). Monitor for secondary cloacal prolapse. Meloxicam 0.5 mg/kg PO q24h post-op.",
        "treatment_ja": "基礎原因の特定と治療。輸液（温乳酸リンゲル50-100 mL/kg/日SC/IO）。エンロフロキサシン15 mg/kg PO/IM q12h（感染が疑われる場合）。補助給餌。保温（28-30℃）。環境管理の改善。",
        "prevention": "適切な飼育管理、バランスの取れた栄養、定期的な獣医師による健康診断、ストレス軽減、初期症状の早期治療が予防に重要である。",
        "prevention_ja": "総排泄腔乳頭腫症の予防にはワクチン接種（利用可能な場合）、新規・病気動物の隔離、厳格なバイオセキュリティ対策、適切な消毒プロトコル、既知のキャリアや汚染環境との接触回避が含まれる。",
        "prognosis": "Generally good to fair with appropriate treatment and follow-up care. Prognosis improves with early diagnosis and owner compliance.",
        "prognosis_ja": "総排泄腔乳頭腫症の予後: 早期発見と適切な治療で多くの疾患は予後良好。慢性疾患は定期的モニタリングと治療調整で長期管理可能。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
