    {
        "name": "Articular Gout",
        "name_ja": "関節痛風",
        "symptoms": {"joint_swelling", "lameness", "white_deposits_on_joints", "lethargy", "appetite_loss", "pain_vocalization"},
        "description": "Articular Gout is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "腎不全による高尿酸血症に伴う関節への尿酸結晶沈着。",
        "urgency": "high",
        "recommended_tests": ["uric_acid_level", "radiography", "joint_aspirate", "renal_panel"],
        "causes": "Uric acid crystal deposition in joints due to hyperuricemia from renal insufficiency.",
        "causes_ja": "鳥における関節痛風の原因: 腎不全による高尿酸血症に伴う関節への尿酸結晶沈着。",
        "pathophysiology": "Articular Gout is a metabolic/endocrine disorder. Uric acid crystal deposition in joints due to hyperuricemia from renal insufficiency. The underlying pathology involves dysregulation of hormonal feedback loops, enzyme activity, or substrate metabolism. This leads to imbalances in circulating hormone levels, electrolytes, or metabolic intermediates that affect cellular function across multiple organ systems. Compensatory mechanisms may temporarily maintain homeostasis but eventually decompensate, leading to progressive clinical deterioration and multi-organ effects.",
        "pathophysiology_ja": "関節痛風は鳥における代謝・内分泌疾患である。基礎病態はホルモンのフィードバックループ、酵素活性、または基質代謝の調節障害を伴う。循環ホルモン、電解質、代謝中間体のバランス異常が複数の臓器系にわたる細胞機能に影響を及ぼす。代償機構が一時的に恒常性を維持するが、最終的に代償不全に陥り、進行性の臨床的悪化と多臓器への影響を引き起こす。",
        "treatment": "Allopurinol 10-30 mg/kg PO q12h to reduce uric acid production. Meloxicam 0.5 mg/kg PO/IM q12-24h for pain and inflammation. SC/IO fluids 25-50 mL/kg/day to promote uric acid excretion. Colchicine 0.04 mg/kg PO q12h for acute flares (use cautiously, narrow therapeutic index). Reduce dietary protein. Correct dehydration. Surgical removal of large tophi if causing functional impairment.",
        "treatment_ja": "鳥における関節痛風の治療は基礎となるホルモン・代謝異常を標的とする。ホルモン補充療法または抑制療法により生理的バランスを回復する。食事療法で代謝疾患の栄養面に対処する。ホルモンレベル、血糖、電解質、臓器機能マーカーの定期的モニタリングにより用量調整を行う。二次的合併症（臓器障害、感染）の併行管理が不可欠である。長期または生涯にわたる治療が必要な場合がある。",
        "prevention": "予防には、適切な食事管理、定期的な血液検査による健康モニタリング、適正体重の維持、過剰なおやつや不適切な食物の回避、無症候性変化の早期介入が重要である。",
        "prevention_ja": "関節痛風の予防には適切な食事設計、血液検査を含む定期的な健康モニタリング、健康体重の維持、過剰なおやつや不適切な食事の回避、無症候性変化の早期発見時の迅速な介入が含まれる。",
        "prognosis": "予後は疾患の重症度、治療介入の時期、治療への反応に依存する。早期診断と適切な治療により転帰が改善する。",
        "prognosis_ja": "関節痛風の予後: 早期発見と適切な治療で多くの疾患は予後良好。慢性疾患は定期的モニタリングと治療調整で長期管理可能。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "young", "senior"},
    },
