    {
        "name": "Egg Binding (Dystocia)",
        "name_ja": "卵詰まり（難産）",
        "symptoms": {"egg_binding", "straining", "lethargy", "fluffed_feathers", "abdominal_distension", "leg_paralysis", "sitting_on_cage_floor"},
        "description": "Egg Binding (Dystocia) is a reproductive condition affecting fertility, gestation, or parturition.",
        "description_ja": "カルシウム欠乏、肥満、卵管機能障害による卵の排出不能。",
        "urgency": "emergency",
        "recommended_tests": ["radiography", "ionized_calcium", "physical_exam", "ultrasound"],
        "causes": "",
        "causes_ja": "両生類における卵詰まり（難産）の原因: 両生類における代謝性の生殖器系疾患。卵詰まり（難産）は適切な診断と治療管理が重要である。早期発見と適切な介入が予後改善の鍵となる。",
        "pathophysiology": "Egg Binding (Dystocia) is a reproductive disorder. Egg Binding (Dystocia) The reproductive pathology involves hormonal imbalances, structural abnormalities, or infectious processes affecting the reproductive tract. Dysregulated sex hormones can lead to cystic changes, hyperplasia, or neoplasia of reproductive organs. Obstetric complications may cause mechanical obstruction or metabolic derangements threatening both mother and offspring. Secondary bacterial infection of the reproductive tract can progress to systemic sepsis.",
        "pathophysiology_ja": "卵詰まり（難産）は両生類における生殖器疾患である。ホルモンバランスの異常、構造異常、または生殖器への感染過程を伴う。性ホルモンの調節障害は生殖器官の嚢胞性変化、過形成、または腫瘍形成を引き起こしうる。産科的合併症は機械的閉塞や代謝異常を引き起こし、母体と産子の両方を脅かす。生殖器の二次細菌感染は全身性敗血症に進行しうる。",
        "treatment": "Warmth (30-32°C) and humidity (60-70%). Calcium gluconate 50-100 mg/kg IM/SC slowly. If no response in 1-2h: oxytocin 3-5 IU/kg IM (single dose, only after calcium supplementation). SC/IO fluids 25-50 mL/kg/day. Meloxicam 0.5 mg/kg IM for pain. If medical management fails: manual extraction under isoflurane anesthesia with lubrication, or surgical salpingotomy. GnRH agonist (leuprolide 0.4-0.8 mg/kg IM) post-resolution to suppress further ovulation.",
        "treatment_ja": "鳥における卵詰まり（難産）の緊急治療: まずグルコン酸カルシウム50-100mg/kg IM（緩徐投与）で子宮筋収縮力を回復。カルシウム投与20-30分後にオキシトシン3-5IU/kg IM（カルシウム投与前のオキシトシン単独投与は効果不十分）。温浴（35-38℃）と高湿度環境（70-80%）で筋弛緩を促進。総排泄腔に水溶性潤滑剤を塗布。静かで暗い環境に安置（30-60分間隔で排卵を確認）。内科的管理に反応しない場合、経総排泄腔的に卵殻を穿刺・吸引し圧壊排出。それでも排出不能な場合は全身麻酔下で外科的卵管切開術。術後はブプレノルフィン鎮痛、補液、保温。慢性的な卵詰まりにはホルモン治療（リュープロライド酢酸塩700-800μg/kg IM）または卵管摘出術を検討。",
        "prevention": "予防には、適切な飼育管理、種に適したバランスの取れた栄養、定期的な獣医師による健康診断、ストレス軽減、清潔な飼育環境の維持、初期臨床徴候への早期対応が重要である。",
        "prevention_ja": "卵詰まり（難産）の予防: 適時の避妊去勢手術（繁殖予定がない場合）。妊娠期の適切な栄養管理。分娩の監視。",
        "prognosis": "Good with timely intervention. Delayed treatment increases risk of uterine rupture, peritonitis, and maternal death.",
        "prognosis_ja": "卵詰まり（難産）の予後: 避妊去勢術で根治可能な疾患が多い。難産は早期介入で母子の予後改善。",
        "onset_pattern": {"acute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
    {
        "name": "Splay Leg (Spraddle Leg)",
        "name_ja": "開脚症",
        "symptoms": {"splay_legs", "inability_to_perch", "lameness", "stunted_growth"},
        "description": "Splay Leg (Spraddle Leg) is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "不適切な床材や栄養不良による幼鳥の片側または両側肢の側方偏位。",
        "urgency": "moderate",
        "recommended_tests": ["physical_exam", "radiography"],
        "causes": "Multifactorial etiology associated with Splay Leg (Spraddle Leg); may involve genetic predisposition, environmental factors, infectious agents, and/or metabolic dysfunction.",
        "causes_ja": "鳥における開脚症の原因: 不適切な床材や栄養不良による幼鳥の片側または両側肢の側方偏位。",
        "pathophysiology": "The pathological process involves tissue injury, inflammatory response, and progressive functional impairment. Without intervention, compensatory mechanisms may be overwhelmed, leading to clinical deterioration.",
        "pathophysiology_ja": "開脚症は鳥における栄養障害である。特定の栄養素の不十分な摂取、吸収不良、または過剰摂取により生じる。欠乏状態では、影響を受けた栄養素を補因子または基質として必要とする生化学的経路が障害され、細胞機能障害を引き起こす。過剰状態では組織への蓄積や栄養素間相互作用の障害により毒性が生じる。種特異的な食事要求により、適切な栄養管理が予防に不可欠である。",
        "treatment": "Hobble brace with tape/foam for neonates (within first 2 weeks). Correct substrate (non-slip). Nutritional assessment. Prognosis good if early.",
        "treatment_ja": "鳥における開脚症の治療は栄養バランスの是正が中心となる。欠乏状態では食事の改善または治療的サプリメンテーションにより特定の栄養素を補充する。過剰状態では食事制限と臓器障害に対する支持療法を行う。栄養不良動物ではリフィーディング症候群予防のため段階的に是正する。種特異的な食事要求に基づく長期栄養計画を立案する。過不足のない摂取を確保するため定期的に再評価する。",
        "prevention": "適切な飼育管理、バランスの取れた栄養、定期的な獣医師による健康診断、ストレス軽減、初期症状の早期治療が予防に重要である。",
        "prevention_ja": "開脚症の予防には全ての栄養要求を満たす種に適した食事設計、単一食品のみの食事の回避、獣医師との定期的な食事内容の見直し、必要時の適切なサプリメンテーション、種固有の栄養ニーズに関する知識が必要である。",
        "prognosis": "Generally good to fair with appropriate treatment and follow-up care. Prognosis improves with early diagnosis and owner compliance.",
        "prognosis_ja": "開脚症の予後: 早期発見と適切な治療で多くの疾患は予後良好。慢性疾患は定期的モニタリングと治療調整で長期管理可能。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
