    {
        "name": "Tracheal Stenosis",
        "name_ja": "気管狭窄症",
        "symptoms": {"cyanosis", "exercise_intolerance", "respiratory_distress", "stridor", "voice_change"},
        "description": "Tracheal Stenosis is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "瘢痕、肉芽腫、先天性奇形による気管内腔の狭窄。",
        "urgency": "high",
        "recommended_tests": ["radiography", "endoscopy", "CT_scan"],
        "causes": "Caused by developmental abnormality of respiratory occurring during embryogenesis. May result from genetic mutations (autosomal dominant, recessive, or polygenic), chromosomal aberrations, or teratogenic exposure. Inbreeding increases risk of congenital defects. Breed-specific predispositions may exist in certain bird lineages.",
        "causes_ja": "胚発生中の呼吸器系発達異常が原因。遺伝子変異（常染色体優性・劣性・多因子性）・染色体異常・催奇形物質曝露に起因しうる。近親交配が先天性欠損のリスクを増加。特定の鳥系統に品種特異的素因が存在しうる。",
        "pathophysiology": "Congenital abnormality of respiratory in bird results from developmental errors during embryogenesis, potentially involving genetic mutations, chromosomal abnormalities, or teratogenic exposure. Structural or functional deficits may be apparent at birth or become clinically significant with growth and maturation. Breed-specific predispositions exist in some bird lineages due to inherited genetic factors.",
        "pathophysiology_ja": "鳥の呼吸器系の先天性異常は、胚発生中の発達エラーに起因し、遺伝子変異・染色体異常・催奇形物質曝露が関与しうる。構造的または機能的欠損は出生時に明らかか、成長に伴い臨床的に顕在化する。一部の鳥系統では遺伝的要因による品種特異的素因が存在する。",
        "treatment": "Surgical correction or stent placement under isoflurane if severe. Dexamethasone 2-4 mg/kg IM for acute edema. Nebulization. Prognosis depends on severity.",
        "treatment_ja": "鳥における気管狭窄症の治療: 抗菌薬（培養感受性に基づく）。ネブライゼーション。酸素療法（重症時）。保温。栄養サポート。環境改善（換気・粉塵低減）。",
        "prevention": "適切な飼育管理、バランスの取れた栄養、定期的な獣医師による健康診断、ストレス軽減、初期症状の早期治療が予防に重要である。",
        "prevention_ja": "予防には適切な飼育管理（適切な食事・清潔な環境・最適な温湿度）；定期的な獣医師の健康診断；新規動物の検疫；ストレス軽減；種特異的予防措置が含まれる",
        "prognosis": "予後は重症度、治療の時期、治療への反応に依存する。早期介入により転帰が改善する。",
        "prognosis_ja": "先天性疾患の予後は異常の種類と重症度に依存する。軽度の機能的異常は管理可能で予後良好。重度の構造的異常は外科的介入が必要な場合があり、予後は変動的。遺伝性疾患の場合、罹患個体の繁殖は避けるべき。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "young", "senior"},
    },
    {
        "name": "Pulmonary Edema",
        "name_ja": "肺水腫",
        "symptoms": {"cyanosis", "lethargy", "open_mouth_breathing", "respiratory_distress", "weakness"},
        "description": "Pulmonary Edema is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "心疾患、毒素、感染症による肺内の液体貯留。",
        "urgency": "emergency",
        "recommended_tests": ["radiography", "echocardiography", "CBC", "blood_chemistry"],
        "causes": "Multifactorial etiology associated with Pulmonary Edema; may involve genetic predisposition, environmental factors, infectious agents, and/or metabolic dysfunction.",
        "causes_ja": "鳥における肺水腫の原因: 感染性病原体（ウイルス、細菌、真菌）、環境刺激物（粉塵、アンモニア）、アレルギー反応、異物誤嚥、解剖学的異常による呼吸器疾患。換気不良がリスクを高める。",
        "pathophysiology": "The pathological process involves tissue injury, inflammatory response, and progressive functional impairment. Without intervention, compensatory mechanisms may be overwhelmed, leading to clinical deterioration.",
        "pathophysiology_ja": "肺水腫は鳥における呼吸器疾患である。気道、肺実質、または胸膜腔の炎症、閉塞、または機能障害を伴う。ガス交換の障害により低酸素血症および高炭酸ガス血症の可能性がある。炎症性滲出液、粘液蓄積、構造変化が有効な換気を低下させる。代償性頻呼吸により呼吸仕事量と代謝要求が増加する。重症例は呼吸不全に進行し緊急介入が必要となりうる。",
        "treatment": "Furosemide 0.1-0.2 mg/kg IM (repeat q4-6h if needed). Oxygen supplementation. Minimize handling and stress. SC fluids cautiously (avoid overhydration). Treat underlying cause: cardiac disease, toxic exposure, or infectious pneumonia. Dexamethasone 2 mg/kg IM single dose if toxic/inflammatory etiology. Keep in warm (28-30°C), quiet, oxygen-enriched environment.",
        "treatment_ja": "酸素療法（酸素室 40-60% O2）を最優先。利尿薬: フロセミド 0.1-0.2mg/kg IM q4-8h（急性期）、安定後 0.05-0.1mg/kg PO q12h。心原性の場合: ピモベンダン 0.25mg/kg PO q12h、ACE阻害薬（ベナゼプリル 0.5mg/kg PO q24h）。輸液過剰が原因の場合は輸液速度の減量・中止。保温（28-30℃）。ストレスを最小限にした環境管理（鳥はストレスに極めて敏感で急変リスクが高い）。疼痛管理（メロキシカム 0.5-1mg/kg PO q12-24h）。呼吸数・開口呼吸のモニタリング。原因疾患（心疾患、毒素暴露、感染）の特定と治療。強制給餌による栄養支持。",
        "prevention": "適切な飼育管理、バランスの取れた栄養、定期的な獣医師による健康診断、ストレス軽減、初期症状の早期治療が予防に重要である。",
        "prevention_ja": "肺水腫の予防: 定期的な健康診断。適切な栄養管理。ストレスの軽減。清潔な飼育環境の維持。異常の早期発見・早期受診。",
        "prognosis": "予後は重症度、基礎疾患、治療の時期に依存する。早期の積極的介入により転帰が改善する。治療の遅延は予後慎重〜不良となる。",
        "prognosis_ja": "肺水腫の予後: 早期発見と適切な治療で多くの疾患は予後良好。慢性疾患は定期的モニタリングと治療調整で長期管理可能。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
