    {
        "name": "Valvular Heart Disease",
        "name_ja": "心臓弁膜症",
        "symptoms": {"abdominal_distension", "exercise_intolerance", "lethargy", "respiratory_distress", "weakness"},
        "description": "Valvular Heart Disease is a cardiovascular condition affecting cardiac function and hemodynamic stability.",
        "description_ja": "心臓弁の変性または感染による心不全。",
        "urgency": "high",
        "recommended_tests": ["echocardiography", "radiography", "auscultation", "electrocardiography"],
        "causes": "Caused by myocardial dysfunction, often due to genetic predisposition, nutritional deficiencies, age-related degeneration, or secondary to systemic disease.",
        "causes_ja": "鳥における心臓弁膜症の原因: 心臓弁の変性または感染による心不全。",
        "pathophysiology": "Myocardial dysfunction impairs cardiac output through reduced contractility, abnormal relaxation, or rhythm disturbances. Compensatory mechanisms eventually fail, leading to congestive heart failure.",
        "pathophysiology_ja": "心臓弁膜症は鳥における循環器疾患である。心臓、大血管、または末梢血管系の構造的・機能的異常を伴う。心拍出量の低下、弁膜機能障害、調律異常により組織灌流が障害される。代償機構（神経ホルモン活性化、心室リモデリング）が一時的に機能を維持するが、進行性の心筋劣化を引き起こす。心不全、血栓塞栓症、突然死が進行期疾患の潜在的結果である。",
        "treatment": "Diuretics (furosemide), ACE inhibitors, pimobendan for systolic dysfunction, antiarrhythmics as indicated, oxygen supplementation, dietary sodium restriction, and activity modification.",
        "treatment_ja": "鳥における心臓弁膜症の治療: うっ血性心不全にフロセミド0.1-0.2mg/kg IM q12h（急性期）→0.1mg/kg PO q12-24h（維持期）。ACE阻害薬: エナラプリル1.25mg/kg PO q12-24h。収縮機能低下にはピモベンダン0.25mg/kg PO q12hを検討。不整脈がある場合は心電図評価後に抗不整脈薬を検討。低ナトリウム食。安静とストレスの軽減が重要（保温28-30℃、静かな環境）。呼吸困難時は酸素投与（40%酸素チャンバー）。定期的な心エコー・X線検査で心拡大と腹水・肝腫大を評価。",
        "prevention": "適切な飼育管理、バランスの取れた栄養、定期的な獣医師による健康診断、ストレス軽減、初期症状の早期治療が予防に重要である。",
        "prevention_ja": "心臓弁膜症の予防: 定期的な心臓検査（聴診、心エコー）。リスク品種のスクリーニング。適切な体重管理と運動量。低ナトリウム食（心不全リスク群）。",
        "prognosis": "予後は疾患の重症度、治療介入の時期、治療への反応に依存する。早期診断と適切な治療により転帰が改善する。",
        "prognosis_ja": "心臓弁膜症の予後: 基礎心疾患の種類と重症度による。軽度は適切な内科管理で長期生存可能。重度心不全は予後要注意。定期的な心エコーによるモニタリングが重要。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "senior"},
    },
