    {
        "name": "Avian Metapneumovirus Rhinotracheitis",
        "name_ja": "鳥メタニューモウイルス性鼻気管炎",
        "symptoms": {"nasal_discharge", "sneezing", "swollen_infraorbital_sinus", "respiratory_distress", "lethargy"},
        "description": "Avian Metapneumovirus Rhinotracheitis is a viral disease that may cause acute or chronic illness with variable clinical presentation.",
        "description_ja": "メタニューモウイルスによる鼻気管炎と二次細菌感染を伴う頭部腫脹症候群。",
        "urgency": "high",
        "recommended_tests": ["PCR_metapneumovirus", "serology", "radiography"],
        "causes": "Caused by viral infection; transmission occurs through direct contact, aerosol, fomites, or vertical transmission.",
        "causes_ja": "鳥における鳥メタニューモウイルス性鼻気管炎の原因: メタニューモウイルスによる鼻気管炎と二次細菌感染を伴う頭部腫脹症候群。",
        "pathophysiology": "Viral particles enter host cells, hijack cellular machinery for replication, and cause cell lysis or immune-mediated damage. The host immune response may contribute to tissue pathology.",
        "pathophysiology_ja": "鳥メタニューモウイルス性鼻気管炎は鳥におけるウイルス感染症である。ウイルスは特定の受容体を介して宿主細胞に侵入し、細胞内機構を利用して複製する。直接的な細胞変性効果（細胞溶解、アポトーシス、標的臓器の組織壊死）を引き起こす。自然免疫（インターフェロン、NK細胞）および適応免疫（抗体、細胞性免疫）の宿主免疫応答が免疫病理に寄与することがある。ウイルス血症により病原体が複数の臓器系に播種される可能性があり、免疫抑制により二次的な細菌・真菌感染のリスクが高まる。",
        "treatment": "Treatment is primarily supportive, including fluid therapy, nutritional support, and secondary infection prevention. Antiviral agents may be used where available and indicated.",
        "treatment_ja": "特異的抗ウイルス治療はない。支持療法：輸液（温乳酸リンゲル50-100 mL/kg/日SC/IO）、保温（28-30℃）、経管栄養または挿管給餌。二次性細菌感染の予防にエンロフロキサシン15 mg/kg PO/IM q12h。メロキシカム0.5-1 mg/kg PO q12-24hで疼痛管理。感染動物の隔離と検疫。環境の消毒。",
        "prevention": "利用可能なワクチン接種、新規動物の検疫、バイオセキュリティ対策、適切な衛生管理、感染動物との接触回避が予防に重要である。",
        "prevention_ja": "鳥メタニューモウイルス性鼻気管炎の予防にはワクチン接種（利用可能な場合）、新規・病気動物の隔離、厳格なバイオセキュリティ対策、適切な消毒プロトコル、既知のキャリアや汚染環境との接触回避が含まれる。",
        "prognosis": "Variable depending on viral agent and host immunity. Mild infections often resolve with supportive care. Severe systemic viral diseases carry a guarded to poor prognosis.",
        "prognosis_ja": "鳥メタニューモウイルス性鼻気管炎の予後: 軽度の上部気道感染は治療に良好に反応。肺炎は早期治療で予後改善。慢性呼吸器疾患は長期管理が必要。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },

