    {
        "name": "Feather Follicle Tumor (Feather Folliculoma)",
        "name_ja": "毛包腫瘍（毛包腫）",
        "symptoms": {"feather_cysts", "feather_loss", "recurrent_lumps", "skin_lesions", "swelling"},
        "description": "Feather Follicle Tumor (Feather Folliculoma) is a neoplastic condition characterized by abnormal cell proliferation that may be benign or malignant.",
        "description_ja": "毛包組織から発生する腫瘍性増殖で、再発性の皮下結節として現れる。",
        "urgency": "moderate",
        "recommended_tests": ["biopsy", "histopathology", "fine_needle_aspirate"],
        "causes": "Neoplastic growth arising from feather follicle tissue, presenting as recurrent subcutaneous nodules.",
        "causes_ja": "鳥における毛包腫瘍（毛包腫）の原因: 毛包組織から発生する腫瘍性増殖で、再発性の皮下結節として現れる。",
        "pathophysiology": "Feather Follicle Tumor (Feather Folliculoma) is a neoplastic condition. Neoplastic growth arising from feather follicle tissue, presenting as recurrent subcutaneous nodules. Neoplastic transformation occurs through accumulated genetic mutations in oncogenes, tumor suppressor genes, and DNA repair mechanisms. Uncontrolled cellular proliferation leads to tumor formation with potential for local tissue invasion and destruction. Malignant neoplasms may metastasize via lymphatic or hematogenous routes. Paraneoplastic syndromes—including hypercalcemia, cachexia, and immune dysregulation—may accompany the primary tumor and contribute to morbidity.",
        "pathophysiology_ja": "毛包腫瘍（毛包腫）は鳥における腫瘍性疾患である。癌遺伝子、腫瘍抑制遺伝子、DNA修復機構における遺伝子変異の蓄積により腫瘍性形質転換が生じる。制御不能な細胞増殖により腫瘍が形成され、局所組織への浸潤・破壊の可能性がある。悪性腫瘍はリンパ行性または血行性に転移しうる。高カルシウム血症、悪液質、免疫調節障害などの腫瘍随伴症候群が原発腫瘍に伴い、罹患率に寄与することがある。",
        "treatment": "Treatment of feather follicle tumor (feather folliculoma) in bird depends on tumor type, location, and stage. Surgical excision with adequate margins is the primary treatment for accessible solid tumors. Chemotherapy may be indicated for systemic neoplasia, incompletely excised tumors, or metastatic disease. Radiation therapy can provide local tumor control. Palliative care focuses on pain management, nutritional support, and maintaining quality of life when curative treatment is not feasible.",
        "treatment_ja": "鳥における毛包腫瘍（毛包腫）の治療: 腫瘍の評価（病理組織検査）に基づく治療計画。外科的切除が可能な場合は第一選択。術後の疼痛管理と栄養サポート。化学療法は腫瘍の種類に応じて検討。緩和ケア（疼痛管理・QOL維持）。",
        "prevention": "腫瘍の予防は限定的である。定期的な健康診断による早期発見が重要。避妊・去勢手術によりホルモン依存性腫瘍のリスクを低減できる場合がある。",
        "prevention_ja": "毛包腫瘍（毛包腫）の予防は限定的であるが、ホルモン依存性腫瘍軽減のための避妊・去勢手術、既知の発癌物質の回避、早期発見のための定期健診、適正体型の維持、該当する場合は遺伝的素因軽減のための責任ある繁殖が含まれる。",
        "prognosis": "予後は腫瘍の種類と病期に依存する。良性腫瘍は完全切除で予後良好。悪性腫瘍はさらなる評価が必要。",
        "prognosis_ja": "毛包腫瘍（毛包腫）の予後: 腫瘍の種類、病期、転移の有無により予後は大きく異なる。早期発見・早期治療で予後改善。悪性腫瘍は一般的に予後要注意〜不良。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "senior"},
    },
