    {
        "name": "Beak Malocclusion – Mandibular Prognathism",
        "name_ja": "嘴不正咬合下顎前突型",
        "symptoms": {"appetite_loss", "beak_deformity", "overgrown_beak", "weight_loss"},
        "description": "Beak Malocclusion – Mandibular Prognathism is a dental condition affecting tooth structure, alignment, or oral health.",
        "description_ja": "下嘴が上嘴を超えて突出し、食物の把持を妨げる。",
        "urgency": "moderate",
        "recommended_tests": ["physical_exam", "radiography"],
        "causes": "Lower beak protrusion beyond the upper beak, interfering with food prehension.",
        "causes_ja": "鳥における嘴不正咬合下顎前突型の原因: 下嘴が上嘴を超えて突出し、食物の把持を妨げる。",
        "pathophysiology": "Beak Malocclusion – Mandibular Prognathism is a dental/oral condition. Lower beak protrusion beyond the upper beak, interfering with food prehension. Dental pathology in this species involves disruption of normal tooth structure, alignment, or supporting tissues. Abnormal tooth growth or wear patterns can lead to malocclusion, root elongation, and periapical abscess formation. Periodontal disease involves bacterial biofilm accumulation, gingival inflammation, and progressive loss of periodontal attachment. Pain from dental disease often manifests as reduced food intake, selective eating, weight loss, and ptyalism.",
        "pathophysiology_ja": "嘴不正咬合下顎前突型は鳥における歯科・口腔疾患である。歯の構造、配列、または支持組織の正常な機能が障害される。異常な歯の成長・摩耗パターンは不正咬合、歯根伸長、根尖膿瘍形成を引き起こしうる。歯周病は細菌バイオフィルムの蓄積、歯肉炎症、歯周付着の進行性喪失を伴う。歯科疾患による疼痛は食欲低下、選択的摂食、体重減少、流涎として現れることが多い。",
        "treatment": "Treatment of beak malocclusion – mandibular prognathism in bird requires dental examination under sedation or anesthesia for thorough assessment. Malocclusion may require tooth trimming, burring, or extraction depending on species and severity. Periapical abscesses require drainage, debridement, and systemic antibiotics. Periodontal disease treatment includes scaling, polishing, and extraction of severely affected teeth. Pain management with species-appropriate analgesics is essential. Dietary modifications support recovery and prevent recurrence.",
        "treatment_ja": "鳥における嘴不正咬合下顎前突型の治療には鎮静または麻酔下での歯科検査が必要である。不正咬合は種と重症度に応じて歯のトリミング、研磨、抜歯が必要となる。根尖膿瘍には排膿、デブリードマン、全身性抗菌薬が必要である。歯周病治療にはスケーリング、研磨、重度罹患歯の抜歯を含む。種に適した鎮痛薬による疼痛管理が不可欠である。食事の調整により回復を促進し再発を予防する。",
        "prevention": "自然な歯の摩耗を促す適切な高繊維食の提供、定期的な歯科検診、選択的摂食の回避が予防に重要である。",
        "prevention_ja": "嘴不正咬合下顎前突型の予防には自然な歯の摩耗を促進する適切な咀嚼材と食事、定期的な歯科検査、発生しつつある不正咬合の早期矯正、種に適した食物繊維の提供が含まれる。",
        "prognosis": "Fair to good with regular dental management. Hereditary malocclusion requires lifelong monitoring and periodic correction.",
        "prognosis_ja": "嘴不正咬合下顎前突型の予後: 早期発見と適切な治療で多くの疾患は予後良好。慢性疾患は定期的モニタリングと治療調整で長期管理可能。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "young", "senior"},
    },
